contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address key) public payable {
        uint256 beforeKey = c.balances(key); if (__ESBMC_reverted()) return;
        uint256 beforeCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterKey = c.balances(key); if (__ESBMC_reverted()) return;
        uint256 afterCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        assert(
            afterKey == beforeKey &&
            afterCaller == beforeCaller &&
            afterContractBalance == beforeContractBalance &&
            afterKey == 0 &&
            afterCaller == 0
        );
    }
}

